use super::*;
use near_sdk::test_utils::{VMContextBuilder, accounts};
use near_sdk::{testing_env, RuntimeFeesConfig};
fn context(who:AccountId,deposit:u128,time:u64) {let mut b=VMContextBuilder::new();b.current_account_id(accounts(5)).predecessor_account_id(who.clone()).signer_account_id(who).attached_deposit(NearToken::from_yoctonear(deposit)).account_balance(NearToken::from_near(100)).block_timestamp(time);testing_env!(b.build());}
fn setup()->Contract {context(accounts(0),0,1);let mut c=Contract::new(accounts(0),250);for who in [accounts(0),accounts(1)] {context(who,ACCOUNT_STORAGE,1);c.register();}context(accounts(0),10u128.pow(24),1);c.nft_mint("collectible-coral".into(),accounts(1),"Coral artifact".into(),"Ownership collectible; not a catch proof".into());c}
fn list(c:&mut Contract){context(accounts(1),LISTING_STORAGE,10);c.list("collectible-coral".into(),U128(10000),U64(100000000000));}
#[test] fn purchase_escrows_and_settles_atomically(){let mut c=setup();list(&mut c);assert_eq!(c.nft_token("collectible-coral".into()).unwrap().owner_id,accounts(5));context(accounts(2),10000,20);c.buy("collectible-coral".into());assert_eq!(c.nft_token("collectible-coral".into()).unwrap().owner_id,accounts(2));assert!(c.listing("collectible-coral".into()).is_none());assert_eq!(c.balance_of(accounts(1)).0,LISTING_STORAGE+9750);assert_eq!(c.balance_of(accounts(0)).0,250);}
#[test] #[should_panic(expected="Exact payment")] fn wrong_payment(){let mut c=setup();list(&mut c);context(accounts(2),9999,20);c.buy("collectible-coral".into());}
#[test] #[should_panic(expected="Exact payment")] fn overpayment(){let mut c=setup();list(&mut c);context(accounts(2),10001,20);c.buy("collectible-coral".into());}
#[test] #[should_panic(expected="Not listed")] fn double_settlement(){let mut c=setup();list(&mut c);context(accounts(2),10000,20);c.buy("collectible-coral".into());c.buy("collectible-coral".into());}
#[test] #[should_panic(expected="unique")] fn duplicate_mint(){let mut c=setup();context(accounts(0),10u128.pow(24),1);c.nft_mint("collectible-coral".into(),accounts(1),"A".into(),"B".into());}
#[test] #[should_panic(expected="Seller must own")] fn unauthorized_listing(){let mut c=setup();context(accounts(0),LISTING_STORAGE,10);c.list("collectible-coral".into(),U128(10000),U64(100000000000));}
#[test] #[should_panic(expected="Listing expired")] fn expired_purchase(){let mut c=setup();list(&mut c);context(accounts(2),10000,100000000000);c.buy("collectible-coral".into());}
#[test] fn delist_refunds_storage_and_returns_token(){let mut c=setup();list(&mut c);context(accounts(1),1,20);c.delist("collectible-coral".into());assert_eq!(c.nft_token("collectible-coral".into()).unwrap().owner_id,accounts(1));assert_eq!(c.balance_of(accounts(1)).0,LISTING_STORAGE);}
#[test] #[should_panic(expected="Fee cap")] fn fee_cap(){context(accounts(0),0,1);Contract::new(accounts(0),501);}
#[test] fn failed_withdrawal_restores_balance(){let mut c=setup();list(&mut c);context(accounts(1),1,20);c.delist("collectible-coral".into());c.withdraw();assert_eq!(c.balance_of(accounts(1)).0,0);let mut b=VMContextBuilder::new();b.current_account_id(accounts(5)).predecessor_account_id(accounts(5)).account_balance(NearToken::from_near(100));testing_env!(b.build(),near_sdk::test_vm_config(),RuntimeFeesConfig::test(),HashMap::default(),vec![PromiseResult::Failed]);assert!(!c.resolve_withdraw(accounts(1),U128(LISTING_STORAGE),false));assert_eq!(c.balance_of(accounts(1)).0,LISTING_STORAGE);}
#[test] fn failed_unregister_keeps_storage_deposit(){let mut c=setup();context(accounts(1),1,20);c.unregister();let mut b=VMContextBuilder::new();b.current_account_id(accounts(5)).predecessor_account_id(accounts(5));testing_env!(b.build(),near_sdk::test_vm_config(),RuntimeFeesConfig::test(),HashMap::default(),vec![PromiseResult::Failed]);assert!(!c.resolve_withdraw(accounts(1),U128(ACCOUNT_STORAGE),true));assert_eq!(c.balance(&accounts(1)).withdrawing,0);}
#[test] #[should_panic(expected="Owner only")] fn admin_protected(){let mut c=setup();context(accounts(1),1,20);c.set_paused(true);}
#[test] fn standard_transfer(){let mut c=setup();context(accounts(1),1,20);c.nft_transfer(accounts(2),"collectible-coral".into(),None,None);assert_eq!(c.nft_token("collectible-coral".into()).unwrap().owner_id,accounts(2));}
